/* @lc app=leetcode id=1697 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = if (p[x] == x) x else find(p, p[x]).also { p[x] = it } fun distanceLimitedPathsExist(n: Int, edgeList: Array<IntArray>, queries: Array<IntArray>): BooleanArray = IntArray(n) { it }.let { p -> edgeList.sortedBy { it[2] }.let { es -> BooleanArray(queries.size).also { res -> queries.indices.sortedBy { queries[it][2] }.fold(0) { ei, qi -> (ei + generateSequence(ei) { it + 1 }.takeWhile { it < es.size && es[it][2] < queries[qi][2] }.onEach { k -> p[find(p, es[k][0])] = find(p, es[k][1]) }.count()).also { res[qi] = find(p, queries[qi][0]) == find(p, queries[qi][1]) } } } } } }